// ─── SAFE STORAGE SHIM ────────────────────────────────────────────────────
const _mem = {};
const safeStorage = {
  async get(key, shared=false) {
    const k = shared ? "shared_"+key : key;
    try { if (window.storage) return await window.storage.get(key, shared); } catch(e){}
    try { const v=localStorage.getItem(k); if(v) return {value:v}; } catch(e){}
    return _mem[k] ? {value:_mem[k]} : null;
  },
  async set(key, value, shared=false) {
    const k = shared ? "shared_"+key : key;
    try { if (window.storage) return await window.storage.set(key, value, shared); } catch(e){}
    try { localStorage.setItem(k, value); } catch(e){}
    _mem[k] = value;
  },
};

